<script lang="ts">import type { PageServerData } from './$types'; let { data }: { data: PageServerData } = $props();</script><svelte:head><title>{data.collection.title} · LinkGarden</title><meta name="description" content={data.collection.description} /><link rel="canonical" href={'/@' + data.routeProfile.username + '/' + data.collection.slug} /></svelte:head><article class="list-header"><p class="eyebrow">Curated list</p><h1>{data.collection.title}</h1><p>{data.collection.description}</p><p>Owned by <a href={'/@' + data.owner.username}>{data.owner.displayName} (@{data.owner.username})</a>{#if data.editors.length} with {data.editors.map((item) => '@' + item.username).join(', ')}{/if}</p></article><ol class="link-list">{#each data.links as item}<li class="card"><h2><a href={item.normalizedUrl} rel="noreferrer">{item.title}</a></h2><p>{item.description}</p>{#if item.tags.length}<ul class="tags" aria-label="Tags">{#each item.tags as name}<li>{name}</li>{/each}</ul>{/if}</li>{:else}<li>This list has no public links yet.</li>{/each}</ol>
